sys_ux_client_script.script:
/**
* @param {Object} params
* @param {Object} params.api
* @param {Object} params.helpers
* @returns {string} A formatted query string containing KPI short descriptions.
*/
function evaluateProperty({ api, helpers }) {
    const kpi = api.data.sam_foundation_current_kpis_1.output.custom_data_entity;

    // Extract first three words from each KPI usecase
    const output = kpi.map(record => 
        record.kpi.split(/\s+/).join(' ')
    );

    console.log("custom data entiittitit",output); // Debugging: Prints extracted short descriptions

    if (output.length > 0) {
        // Join the short descriptions with commas
        const query = `short_descriptionIN${output.join(',')}`;

        console.log("custom dataaaaaefefefvfve",query); // Debugging: Logs final query format
        return query;
    }

    // Default return value if no data exists
    return "short_descriptionINUsers Without Email ID,Users Without Department";
}
